    statusText.style.color = '#ff5d5d';
  } else if (fuel <= 25) {
    statusText.textContent = 'Fire almost out';
    statusText.style.color = '#ff5d5d';
  } else if (fuel <= 55) {
    statusText.textContent = 'Fire is low';
    statusText.style.color = '#ffba58';
