input.content:
import puppeteer from 'puppeteer-core';

const wait = (ms) => new Promise((r) => setTimeout(r, ms));
const results = [];
function check(name, pass, detail = '') {
  results.push({ name, pass, detail });
  console.log(`${pass ? 'PASS' : 'FAIL'} - ${name}${detail ? ` :: ${detail}` : ''}`);
}

const browser = await puppeteer.launch({
  executablePath: '/usr/bin/chromium',
  headless: 'new',
  args: ['--no-sandbox', '--disable-setuid-sandbox', '--disable-dev-shm-usage', '--enable-unsafe-swiftshader']
});
const page = await browser.newPage();
await page.setViewport({ width: 1280, height: 800, deviceScaleFactor: 1 });

const consoleErrors = [];
const pageErrors = [];
page.on('console', (msg) => {
  if (msg.type() === 'error') consoleErrors.push(msg.text());
});
page.on('pageerror', (err) => pageErrors.push(String(err)));

await page.goto('http://localhost:3002/', { waitUntil: 'domcontentloaded' });
await page.waitForFunction(() => window.__nightsDebug);
await wait(500);

const initial = await page.evaluate(() => ({
  night: document.getElementById('nightText').textContent,
  phaseNight: document.getElementById('phaseIcon').classList.contains('night'),
  sapling: document.getElementById('saplingText').textContent,
  health: document.getElementById('healthText').textContent
}));
check('HUD starts at Night 1 / 99', initial.night === '1 / 99', initial.night);
check('HUD day icon shown at start', initial.phaseNight === false);
check('HUD sapling counter starts at 0', initial.sapling === '0');

await page.click('#startBtn');
await wait(400);
const started = await page.evaluate(() => ({
  started: window.__nightsDebug.state.started,
  paused: document.getElementById('startOverlay').classList.contains('hidden'),
  cycle: window.__nightsDebug.state.cycleTime,
  daylight: window.__nightsDebug.state.daylight
}));
check('Game starts on a bright day', started.started && started.paused && started.daylight > 0.95, JSON.stringify(started));
await page.screenshot({ path: '/tmp/opencode/browser-test/day.png' });

await page.keyboard.press('Space');
await wait(80);
const attackState = await page.evaluate(() => ({
  timer: window.__nightsDebug.state.attackTimer,
  cooldown: window.__nightsDebug.state.attackCooldown
}));
check('Attack swings on Space', attackState.timer > 0 && attackState.cooldown > 0, JSON.stringify(attackState));

// Force nightfall
await page.evaluate(() => {
  const d = window.__nightsDebug;
  d.state.cycleTime = 180 - 0.02;
});
await wait(600);
const nightState = await page.evaluate(() => {
  const d = window.__nightsDebug;
  const visible = d.enemies.filter((e) => e.visible && !e.userData.dead);
  const groundErrors = visible.map((e) => Math.abs(e.position.y - d.getGroundHeight(e.position.x, e.position.z)));
  return {
    daylight: d.state.daylight,
    nightActive: d.state.nightActive,
    visible: visible.length,
    nightText: document.getElementById('nightText').textContent,
    phaseNight: document.getElementById('phaseIcon').classList.contains('night'),
    maxGroundError: Math.max(0, ...groundErrors)
  };
});
check('Night falls with smooth daylight drop', nightState.daylight < 0.1 && nightState.nightActive, JSON.stringify(nightState));
check('Night 1 spawns exactly 2 monsters', nightState.visible === 2, `visible=${nightState.visible}`);
check('HUD shows night icon at night', nightState.phaseNight === true && nightState.nightText === '1 / 99');
check('Monsters stay on the ground', nightState.maxGroundError < 0.001, `err=${nightState.maxGroundError}`);
await page.screenshot({ path: '/tmp/opencode/browser-test/night.png' });

const approach = await page.evaluate(async () => {
  const d = window.__nightsDebug;
  const e = d.enemies.find((x) => x.visible && !x.userData.dead);
  const before = Math.hypot(e.position.x - d.player.position.x, e.position.z - d.player.position.z);
  await new Promise((r) => setTimeout(r, 2500));
  const after = Math.hypot(e.position.x - d.player.position.x, e.position.z - d.player.position.z);
  return { before, after, legRot: e.userData.legs[0].rotation.x, phase: e.userData.phase };
});
check('Monsters walk toward the camp/player', approach.after < approach.before, JSON.stringify(approach));
check('Monsters play a walking animation', Math.abs(approach.legRot) > 0.01, `leg=${approach.legRot}`);

// Fire scares monsters while strong
await page.evaluate(() => {
  const d = window.__nightsDebug;
  d.state.fuel = 100;
  d.state.fireOut = false;
  d.state.health = 100;
  d.state.invuln = 999;
  for (const e of d.enemies) {
    if (e.visible) {
      e.position.set(5, d.getGroundHeight(5, 0), 0);
      e.userData.speed = 2;
      e.userData.attackCooldown = 99;
    }
  }
});
await wait(1400);
const scared = await page.evaluate(() => {
  const d = window.__nightsDebug;
  return d.enemies.filter((e) => e.visible && !e.userData.dead).map((e) => Math.hypot(e.position.x, e.position.z));
});
check('Strong fire keeps monsters ~6m away', scared.length > 0 && scared.every((dist) => dist >= 5.85), JSON.stringify(scared));

// Fire out lets them approach
await page.evaluate(() => {
  const d = window.__nightsDebug;
  d.state.fuel = 0;
  d.state.fireOut = true;
  for (const e of d.enemies) {
    if (e.visible) {
      e.position.set(5.3, d.getGroundHeight(5.3, 0), 0);
      e.userData.speed = 2.2;
      e.userData.attackCooldown = 99;
    }
  }
});
await wait(2200);
const freeAttack = await page.evaluate(() => {
  const d = window.__nightsDebug;
  return d.enemies.filter((e) => e.visible && !e.userData.dead).map((e) => Math.hypot(e.position.x, e.position.z));
});
check('Dead fire lets monsters come inside 6m', freeAttack.length > 0 && freeAttack.some((dist) => dist < 5.2), JSON.stringify(freeAttack));

// Combat: damage, red flash, knockback, hit effect
await page.evaluate(() => {
  const d = window.__nightsDebug;
  d.state.fuel = 100;
  d.state.fireOut = false;
  d.state.invuln = 999;
  d.player.position.set(16, d.getGroundHeight(16, 16), 16);
  d.player.rotation.y = 0;
  for (let i = 0; i < d.enemies.length; i += 1) {
    const e = d.enemies[i];
    if (i === 0) {
      e.visible = true;
      e.userData.dead = false;
      e.userData.fading = false;
      e.userData.health = 3;
      e.userData.speed = 0.1;
      e.userData.bodyMat.opacity = 1;
      e.userData.bodyMat.transparent = false;
      e.userData.bodyMat.emissive.setHex(0x000000);
      e.userData.bodyMat.emissiveIntensity = 1;
      e.userData.eyeMat.opacity = 1;
      e.userData.eyeMat.transparent = false;
      e.position.set(16, d.getGroundHeight(16, 18.4), 18.4);
      e.userData.knockback.set(0, 0, 0);
      e.userData.attackCooldown = 99;
    } else {
      e.visible = false;
    }
  }
});
await wait(200);
const beforeHit = await page.evaluate(() => {
  const d = window.__nightsDebug;
  return { z: d.enemies[0].position.z, health: d.enemies[0].userData.health };
});
await page.keyboard.press('Space');
await wait(70);
const hit = await page.evaluate(() => {
  const d = window.__nightsDebug;
  const e = d.enemies[0];
  return {
    health: e.userData.health,
    emissiveHex: e.userData.bodyMat.emissive.getHex(),
    emissive: e.userData.bodyMat.emissiveIntensity,
    knockback: e.userData.knockback.length(),
    effect: !!(d.state.hitEffectTimer > 0),
    z: e.position.z
  };
});
check('Axe hit damages a monster', hit.health === beforeHit.health - 1, JSON.stringify({ beforeHit, hit }));
check('Hit flashes the monster red', hit.emissiveHex === 0xff2f1a && hit.emissive > 0.5, JSON.stringify(hit));
check('Hit knocks the monster back', hit.knockback > 0.5, JSON.stringify(hit));
check('Hit effect is visible', hit.effect === true);

// Player damage and health bar
const damage = await page.evaluate(async () => {
  const d = window.__nightsDebug;
  d.state.invuln = 0;
  d.state.health = 60;
  const e = d.enemies[0];
  e.userData.speed = 0;
  e.position.set(d.player.position.x, d.getGroundHeight(d.player.position.x, d.player.position.z), d.player.position.z);
  e.userData.attackCooldown = 0;
  e.userData.health = 99;
  await new Promise((r) => setTimeout(r, 700));
  return {
    health: d.state.health,
    text: document.getElementById('healthText').textContent,
    bar: document.getElementById('healthFill').style.width
  };
});
check('Monsters damage the player on touch', damage.health < 60, JSON.stringify(damage));
check('Health HUD updates with the damage', damage.text === String(Math.ceil(damage.health)) && damage.bar !== '60%', JSON.stringify(damage));

// Death and respawn at the start of the same night
const death = await page.evaluate(async () => {
  const d = window.__nightsDebug;
  d.state.health = 1;
  d.state.invuln = 0;
  const e = d.enemies[0];
  e.userData.speed = 0;
  e.position.set(d.player.position.x, d.getGroundHeight(d.player.position.x, d.player.position.z), d.player.position.z);
  e.userData.attackCooldown = 0;
  await new Promise((r) => setTimeout(r, 700));
  const banner = document.getElementById('deathBanner').classList.contains('visible');
  const falling = d.state.falling;
  d.state.falling = 0.02;
  await new Promise((r) => setTimeout(r, 700));
  return {
    banner,
    falling,
    afterFalling: d.state.falling,
    health: d.state.health,
    cycle: d.state.cycleTime,
    nightActive: d.state.nightActive,
    playerDist: Math.hypot(d.player.position.x, d.player.position.z),
    visible: d.enemies.filter((x) => x.visible && !x.userData.dead).length
  };
});
check('Death shows "You fell"', death.banner === true && death.falling > 0, JSON.stringify(death));
check('Respawn returns to camp at night start', death.health === 100 && death.afterFalling === 0 && death.playerDist < 5 && death.cycle < 181 && death.nightActive, JSON.stringify(death));
check('Night wave restarts with the same night count', death.visible === 2, `visible=${death.visible}`);

// Trees drop 3 logs + 1 sapling and fall over
const treeTest = await page.evaluate(async () => {
  const d = window.__nightsDebug;
  d.state.invuln = 999;
  d.state.falling = 0;
  const tree = d.treeData.find((t) => t.userData.choppable && !t.userData.falling && t.visible);
  d.player.position.set(tree.position.x + 1.55, d.getGroundHeight(tree.position.x + 1.55, tree.position.z), tree.position.z);
  d.player.rotation.y = Math.atan2(tree.position.x - d.player.position.x, tree.position.z - d.player.position.z);
  await new Promise((r) => setTimeout(r, 400));
  const target = d.state.targetTree === tree;
  for (let i = 0; i < 3; i += 1) {
    d.state.interactCooldown = 0;
    d.interact();
    await new Promise((r) => setTimeout(r, 60));
  }
  const falling = tree.userData.falling === true;
  const rotationBefore = tree.quaternion.length();
  // Move away before loot auto-collects, then finish the fall immediately.
  d.player.position.set(20, d.getGroundHeight(20, 20), 20);
  tree.userData.fallProgress = 0.98;
  await new Promise((r) => setTimeout(r, 900));
  return {
    target,
    falling,
    rotationBefore,
    visible: tree.visible,
    fallen: tree.userData.fallProgress,
    logs: d.droppedLogs.length,
    saplings: d.droppedSaplings.length,
    wood: d.state.wood
  };
});
check('Interact selects a nearby tree', treeTest.target === true);
check('Chopped tree falls over', treeTest.falling === true && treeTest.fallen >= 1, JSON.stringify(treeTest));
check('Fallen tree drops 3 logs and 1 sapling', treeTest.logs === 3 && treeTest.saplings === 1, JSON.stringify(treeTest));

// Sapling pickup
const pickup = await page.evaluate(async () => {
  const d = window.__nightsDebug;
  const sap = d.droppedSaplings[0];
  if (!sap) return { missing: true };
  sap.pickupDelay = 0;
  d.player.position.set(sap.x, d.getGroundHeight(sap.x, sap.z), sap.z);
  await new Promise((r) => setTimeout(r, 700));
  return {
    saplings: d.state.saplings,
    remaining: d.droppedSaplings.length,
    hud: document.getElementById('saplingText').textContent,
    buttonVisible: document.getElementById('plantBtn').classList.contains('visible')
  };
});
check('Sapling can be picked up', pickup.saplings >= 1, JSON.stringify(pickup));
check('Sapling HUD count updates', pickup.hud === '1', JSON.stringify(pickup));
check('Plant button appears while holding a sapling', pickup.buttonVisible === true, JSON.stringify(pickup));

// Plant and grow
const planted = await page.evaluate(async () => {
  const d = window.__nightsDebug;
  d.state.falling = 0;
  d.player.position.set(0, d.getGroundHeight(0, -8), -8);
  d.player.rotation.y = 0;
  await new Promise((r) => setTimeout(r, 200));
  const before = d.state.saplings;
  document.getElementById('plantBtn').dispatchEvent(new PointerEvent('pointerdown', { bubbles: true }));
  await new Promise((r) => setTimeout(r, 300));
  const after = d.state.saplings;
  const plantedCount = d.plantedSaplings.length;
  if (plantedCount > 0) d.plantedSaplings[0].growth = 44.8;
  await new Promise((r) => setTimeout(r, 900));
  const grown = d.treeData.filter((t) => t.userData.planted);
  return {
    before,
    after,
    plantedCount,
    grown: grown.length,
    choppable: grown[0]?.userData.choppable === true,
    saplings: d.state.saplings
  };
});
check('Plant consumes a sapling and places it in front', planted.after === planted.before - 1 && planted.plantedCount === 1, JSON.stringify(planted));
check('Planted sapling grows into a choppable tree', planted.grown >= 1 && planted.choppable, JSON.stringify(planted));

// Sunrise fade
const sunrise = await page.evaluate(async () => {
  const d = window.__nightsDebug;
  d.spawnNightWave();
  d.state.cycleTime = 285.9;
  await new Promise((r) => setTimeout(r, 900));
  const fading = d.enemies.filter((e) => e.visible && e.userData.fading).length;
  for (const e of d.enemies) if (e.visible) e.userData.fade = 0.01;
  await new Promise((r) => setTimeout(r, 700));
  const visible = d.enemies.filter((e) => e.visible).length;
  return { fading, visible, daylight: d.state.daylight };
});
check('Monsters fade at sunrise', sunrise.fading > 0 && sunrise.visible === 0, JSON.stringify(sunrise));

// Night increments at the end of the cycle
const increment = await page.evaluate(async () => {
  const d = window.__nightsDebug;
  d.state.night = 1;
  d.state.cycleTime = 299.97;
  await new Promise((r) => setTimeout(r, 700));
  return { night: d.state.night, text: document.getElementById('nightText').textContent };
});
check('Night count advances after surviving', increment.night === 2 && increment.text === '2 / 99', JSON.stringify(increment));

// Victory on surviving night 99
const victory = await page.evaluate(async () => {
  const d = window.__nightsDebug;
  d.state.night = 99;
  d.state.cycleTime = 299.97;
  await new Promise((r) => setTimeout(r, 700));
  return {
    victory: d.state.victory,
    title: document.querySelector('#startOverlay .title').textContent,
    visible: !document.getElementById('startOverlay').classList.contains('hidden')
  };
});
check('Surviving night 99 wins the game', victory.victory && victory.title === 'You Survived' && victory.visible, JSON.stringify(victory));

check('No uncaught page errors', pageErrors.length === 0, pageErrors.join(' | '));
check('No console errors', consoleErrors.length === 0, consoleErrors.join(' | '));

await page.screenshot({ path: '/tmp/opencode/browser-test/final.png' });
await browser.close();

const failed = results.filter((r) => !r.pass);
console.log(`\n${results.length - failed.length}/${results.length} checks passed`);
if (failed.length > 0) {
  console.log('FAILED CHECKS:');
  for (const f of failed) console.log(` - ${f.name} :: ${f.detail}`);
  process.exit(1);
