import puppeteer from 'puppeteer-core';

const wait = (ms) => new Promise((r) => setTimeout(r, ms));
const results = [];
function check(name, pass, detail = '') {
  results.push({ name, pass, detail });
  console.log(`${pass ? 'PASS' : 'FAIL'} - ${name}${detail ? ` :: ${detail}` : ''}`);
}

const browser = await puppeteer.launch({
  executablePath: '/usr/bin/chromium',
  headless: 'new',
  args: ['--no-sandbox', '--disable-setuid-sandbox', '--disable-dev-shm-usage', '--enable-unsafe-swiftshader']
});
const page = await browser.newPage();
await page.setViewport({ width: 740, height: 360, isMobile: true, hasTouch: true, deviceScaleFactor: 2 });

const consoleErrors = [];
const pageErrors = [];
page.on('console', (msg) => { if (msg.type() === 'error') consoleErrors.push(msg.text()); });
page.on('pageerror', (err) => pageErrors.push(String(err)));

await page.goto('http://localhost:3002/', { waitUntil: 'domcontentloaded' });
await page.waitForFunction(() => window.__nightsDebug, { timeout: 20000 });
await wait(500);

const initial = await page.evaluate(() => ({
  portrait: window.__nightsDebug.state.portrait,
  paused: window.__nightsDebug.state.paused,
  rotate: getComputedStyle(document.getElementById('rotateOverlay')).display,
  berries: window.__nightsDebug.groundItems.filter((i) => i.type === 'berry').length,
  bushes: window.__nightsDebug.berryBushes.length,
  hotbarSlots: document.querySelectorAll('.hotbar-slot').length,
  attackVisible: document.getElementById('attackBtn').classList.contains('visible')
}));
check('Landscape starts unpaused without rotate overlay', !initial.portrait && !initial.paused && initial.rotate === 'none', JSON.stringify(initial));
check('Berry bushes already provide ground berries before start', initial.berries >= 30 && initial.bushes >= 10, JSON.stringify(initial));
check('Hotbar has exactly Axe and Backpack slots', initial.hotbarSlots === 2, `slots=${initial.hotbarSlots}`);
check('Attack button hidden with no axe equipped', initial.attackVisible === false);

await page.tap('#startBtn');
await wait(600);
const started = await page.evaluate(() => ({
  started: window.__nightsDebug.state.started,
  overlayHidden: document.getElementById('startOverlay').classList.contains('hidden'),
  equipped: window.__nightsDebug.state.equippedTool,
  hunger: window.__nightsDebug.state.hunger,
  berries: window.__nightsDebug.groundItems.filter((i) => i.type === 'berry').length,
  rotate: getComputedStyle(document.getElementById('rotateOverlay')).display
}));
check('Game starts in landscape', started.started && started.overlayHidden && started.rotate === 'none', JSON.stringify(started));
check('HUD starts with full hunger', started.hunger >= 99.5, JSON.stringify(started));
check('Start repopulates berries without duplicating them', started.berries >= 30 && started.berries <= 60, JSON.stringify(started));

// Hotbar equip / unequip.
await page.tap('#axeSlot');
await wait(200);
const axeEquipped = await page.evaluate(() => ({
  tool: window.__nightsDebug.state.equippedTool,
  slot: document.getElementById('axeSlot').classList.contains('equipped'),
  axeVisible: window.__nightsDebug.axe.visible,
  backpackVisible: window.__nightsDebug.handBackpack.visible,
  attackVisible: document.getElementById('attackBtn').classList.contains('visible'),
  label: document.getElementById('attackLabel').textContent,
  slotTransform: getComputedStyle(document.getElementById('axeSlot')).transform
}));
check('Tapping Axe equips it in the right hand', axeEquipped.tool === 'axe' && axeEquipped.slot && axeEquipped.axeVisible && !axeEquipped.backpackVisible, JSON.stringify(axeEquipped));
check('Attack button appears only with the axe', axeEquipped.attackVisible === true);
check('Selected slot is lifted and scaled', axeEquipped.slotTransform !== 'none' && axeEquipped.slotTransform !== 'matrix(1, 0, 0, 1, 0, 0)', axeEquipped.slotTransform);

await page.tap('#axeSlot');
await wait(200);
const axeUnequipped = await page.evaluate(() => ({
  tool: window.__nightsDebug.state.equippedTool,
  slot: document.getElementById('axeSlot').classList.contains('equipped'),
  axeVisible: window.__nightsDebug.axe.visible,
  attackVisible: document.getElementById('attackBtn').classList.contains('visible')
}));
check('Tapping the equipped Axe unequips it', axeUnequipped.tool === null && !axeUnequipped.slot && !axeUnequipped.axeVisible && !axeUnequipped.attackVisible, JSON.stringify(axeUnequipped));

await page.tap('#backpackSlot');
await wait(200);
const backpackEquipped = await page.evaluate(() => ({
  tool: window.__nightsDebug.state.equippedTool,
  slot: document.getElementById('backpackSlot').classList.contains('equipped'),
  handVisible: window.__nightsDebug.handBackpack.visible,
  axeVisible: window.__nightsDebug.axe.visible,
  attackVisible: document.getElementById('attackBtn').classList.contains('visible'),
  badge: document.getElementById('backpackBadge').textContent,
  modelChildren: window.__nightsDebug.handBackpack.children.length
}));
check('Tapping Backpack equips it in the right hand', backpackEquipped.tool === 'backpack' && backpackEquipped.slot && backpackEquipped.handVisible && !backpackEquipped.axeVisible, JSON.stringify(backpackEquipped));
check('Backpack badge starts at 0/20', backpackEquipped.badge === '0/20', backpackEquipped.badge);
check('Backpack hand model has bag, flap and strap parts', backpackEquipped.modelChildren >= 5, `children=${backpackEquipped.modelChildren}`);
check('Only one tool is equipped at a time', backpackEquipped.attackVisible === false);

// No auto pickup.
const autoPickup = await page.evaluate(async () => {
  const d = window.__nightsDebug;
  d.unequipTool();
  d.state.backpack.wood = 0;
  d.state.backpack.sapling = 0;
  d.state.backpack.berry = 0;
  d.player.position.set(20, d.getGroundHeight(20, 20), 20);
  const item = d.spawnGroundItem('wood', 20, 20, { velocityY: 0, pickupDelay: 0 });
  item.landed = true;
  item.mesh.position.y = item.groundY + item.restY;
  await new Promise((r) => setTimeout(r, 900));
  return {
    stillGround: d.groundItems.includes(item),
    carried: d.carriedItems.length,
    backpack: d.state.backpack.wood,
    itemCarried: item.carried
  };
});
check('Walking over an item does not auto-collect it', autoPickup.stillGround && !autoPickup.itemCarried && autoPickup.carried === 0 && autoPickup.backpack === 0, JSON.stringify(autoPickup));

// Interact to carry.
const carry = await page.evaluate(async () => {
  const d = window.__nightsDebug;
  d.unequipTool();
  d.state.interactCooldown = 0;
  const item = d.findNearestGroundItem(5, (i) => i.type === 'wood');
  const before = { carried: d.carriedItems.length, x: item.mesh.position.x, z: item.mesh.position.z };
  d.interact();
  await new Promise((r) => setTimeout(r, 500));
  return {
    before,
    carried: d.carriedItems.length,
    itemCarried: item.carried,
    follows: Math.hypot(item.mesh.position.x - before.x, item.mesh.position.z - before.z) > 0.05,
    hudWood: document.getElementById('woodText').textContent
  };
});
check('Interact picks up a nearby item', carry.carried === 1 && carry.itemCarried === true, JSON.stringify(carry));
check('Carried item lifts and follows the player', carry.follows === true, JSON.stringify(carry));
check('HUD counter includes carried items', carry.hudWood === '1', carry.hudWood);

// Tapping a world item picks it up.
const tapPickup = await page.evaluate(async () => {
  const d = window.__nightsDebug;
  const THREE = await import('three');
  const item = d.spawnGroundItem('wood', d.player.position.x + 1.1, d.player.position.z + 0.4, { velocityY: 0, pickupDelay: 0 });
  item.landed = true;
  item.mesh.position.y = item.groundY + item.restY + 0.2;
  await new Promise((r) => setTimeout(r, 120));
  const v = new THREE.Vector3(item.mesh.position.x, item.mesh.position.y, item.mesh.position.z).project(d.camera);
  const rect = d.canvas.getBoundingClientRect();
  const x = rect.left + ((v.x + 1) / 2) * rect.width;
  const y = rect.top + ((1 - v.y) / 2) * rect.height;
  d.handleWorldTap(x, y);
  await new Promise((r) => setTimeout(r, 150));
  return { carried: d.carriedItems.length, itemCarried: item.carried };
});
check('Tapping a nearby world item picks it up', tapPickup.carried === 2 && tapPickup.itemCarried === true, JSON.stringify(tapPickup));

// Carry limit of 3.
const carryLimit = await page.evaluate(async () => {
  const d = window.__nightsDebug;
  const before = d.carriedItems.length;
  for (let i = 0; i < 4; i += 1) {
    const item = d.spawnGroundItem('wood', d.player.position.x + 0.8, d.player.position.z + i * 0.2, { velocityY: 0, pickupDelay: 0 });
    item.landed = true;
    item.mesh.position.y = item.groundY + item.restY;
    d.pickUpItem(item);
  }
  await new Promise((r) => setTimeout(r, 300));
  return { before, carried: d.carriedItems.length, toast: document.getElementById('toast').textContent };
});
check('Player can carry at most 3 items', carryLimit.carried === 3, JSON.stringify(carryLimit));

// Drop all floating items through the button.
const dropped = await page.evaluate(async () => {
  const d = window.__nightsDebug;
  d.state.dropCooldown = 0;
  const before = d.carriedItems.length;
  document.getElementById('dropBtn').dispatchEvent(new PointerEvent('pointerdown', { bubbles: true }));
  await new Promise((r) => setTimeout(r, 400));
  return { before, carried: d.carriedItems.length, ground: d.groundItems.filter((i) => !i.carried && i.mesh.parent).length, toast: document.getElementById('toast').textContent };
});
check('Drop button releases all floating items to the ground', dropped.before === 3 && dropped.carried === 0 && dropped.ground >= 3, JSON.stringify(dropped));

// Backpack pickup, pop animation and badge.
const backpackPickup = await page.evaluate(async () => {
  const d = window.__nightsDebug;
  d.state.backpack.wood = 0;
  d.state.backpack.sapling = 0;
  d.state.backpack.berry = 0;
  d.equipTool('backpack');
  const item = d.spawnGroundItem('berry', d.player.position.x + 0.9, d.player.position.z, { velocityY: 0, pickupDelay: 0 });
  item.landed = true;
  item.mesh.position.y = item.groundY + item.restY;
  const picked = d.pickUpItem(item);
  const immediately = {
    picked,
    berry: d.state.backpack.berry,
    popping: item.popping,
    badge: document.getElementById('backpackBadge').textContent,
    popClass: document.getElementById('backpackSlot').classList.contains('pop')
  };
  await new Promise((r) => setTimeout(r, 950));
  return {
    immediately,
    remains: d.groundItems.includes(item),
    inScene: item.mesh.parent !== null,
    badge: document.getElementById('backpackBadge').textContent
  };
});
check('Backpack equipped sends tapped items straight into the bag', backpackPickup.immediately.picked && backpackPickup.immediately.berry === 1, JSON.stringify(backpackPickup));
check('Backpack item and slot play a pop animation', backpackPickup.immediately.popping > 0 && backpackPickup.immediately.popClass === true, JSON.stringify(backpackPickup));
check('Backpack badge updates to 1/20', backpackPickup.badge === '1/20', backpackPickup.badge);
check('Popped world item is removed', backpackPickup.remains === false && backpackPickup.inScene === false, JSON.stringify(backpackPickup));

// Capacity limit.
const capacity = await page.evaluate(async () => {
  const d = window.__nightsDebug;
  d.state.backpack.wood = 20;
  d.state.backpack.berry = 0;
  d.state.backpack.sapling = 0;
  const item = d.spawnGroundItem('sapling', d.player.position.x + 0.8, d.player.position.z + 0.5, { velocityY: 0, pickupDelay: 0 });
  item.landed = true;
  item.mesh.position.y = item.groundY + item.restY;
  const picked = d.pickUpItem(item);
  await new Promise((r) => setTimeout(r, 120));
  return { picked, sapling: d.state.backpack.sapling, badge: document.getElementById('backpackBadge').textContent, toast: document.getElementById('toast').textContent };
});
check('Backpack capacity is capped at 20 items', capacity.picked === false && capacity.sapling === 0 && capacity.toast.includes('full'), JSON.stringify(capacity));

// Inventory panel opens on second backpack tap.
await page.tap('#backpackSlot');
await wait(250);
const inventory = await page.evaluate(() => ({
  open: !document.getElementById('inventoryPanel').classList.contains('hidden'),
  rows: document.querySelectorAll('.inventory-row').length,
  capacity: document.getElementById('inventoryCapacity').textContent,
  takeButtons: document.querySelectorAll('.inv-btn.take').length,
  close: !!document.getElementById('closeInventoryBtn'),
  closeBox: document.getElementById('closeInventoryBtn').getBoundingClientRect().toJSON(),
  panelBox: document.getElementById('inventoryPanel').getBoundingClientRect().toJSON()
}));
check('Tapping equipped Backpack opens the inventory panel', inventory.open === true && inventory.rows >= 1, JSON.stringify(inventory));
check('Inventory shows counts, Take and a close button', inventory.capacity === '20 / 20' && inventory.takeButtons >= 1 && inventory.close, JSON.stringify(inventory));
check('Inventory close button is thumb-sized', inventory.closeBox.width >= 30 && inventory.closeBox.height >= 30, JSON.stringify(inventory.closeBox));
check('Inventory panel stays inside the viewport', inventory.panelBox.left >= 0 && inventory.panelBox.right <= 740 && inventory.panelBox.top >= 0, JSON.stringify(inventory.panelBox));

// Take out through the panel.
const inventoryTake = await page.evaluate(async () => {
  const d = window.__nightsDebug;
  d.state.backpack.wood = 2;
  d.updateHud();
  await new Promise((r) => setTimeout(r, 60));
  const take = document.querySelector('.inv-btn.take');
  const groundBefore = d.groundItems.filter((i) => i.mesh.parent).length;
  take.dispatchEvent(new PointerEvent('pointerdown', { bubbles: true }));
  await new Promise((r) => setTimeout(r, 300));
  return { wood: d.state.backpack.wood, groundBefore, groundAfter: d.groundItems.filter((i) => i.mesh.parent).length, capacity: document.getElementById('inventoryCapacity').textContent };
});
check('Taking an item out removes it from the bag and drops it in front', inventoryTake.wood === 1 && inventoryTake.groundAfter === inventoryTake.groundBefore + 1, JSON.stringify(inventoryTake));

await page.evaluate(() => window.__nightsDebug.setInventoryOpen(false));

// Drop a backpack item when hands are empty.
const backpackDrop = await page.evaluate(async () => {
  const d = window.__nightsDebug;
  d.carriedItems.splice(0);
  d.state.backpack.wood = 2;
  d.state.dropCooldown = 0;
  const before = d.groundItems.filter((i) => i.mesh.parent).length;
  d.dropCarriedItems();
  await new Promise((r) => setTimeout(r, 250));
  return { wood: d.state.backpack.wood, before, after: d.groundItems.filter((i) => i.mesh.parent).length, toast: document.getElementById('toast').textContent };
});
check('Dropping a backpack item takes it out in front', backpackDrop.wood === 1 && backpackDrop.after === backpackDrop.before + 1, JSON.stringify(backpackDrop));

// Throw carried items into the fire.
const fire = await page.evaluate(async () => {
  const d = window.__nightsDebug;
  d.unequipTool();
  d.carriedItems.splice(0);
  d.state.backpack.wood = 0;
  d.player.position.set(0, d.getGroundHeight(0, 2.2), 2.2);
  d.state.fuel = 30;
  d.state.fireOut = false;
  const item = d.spawnGroundItem('wood', 0.8, 2.2, { velocityY: 0, pickupDelay: 0 });
  item.landed = true;
  item.mesh.position.y = item.groundY + item.restY;
  d.pickUpItem(item);
  d.state.interactCooldown = 0;
  await new Promise((r) => setTimeout(r, 250));
  const label = document.getElementById('interactLabel').textContent;
  d.interact();
  await new Promise((r) => setTimeout(r, 300));
  return { fuel: d.state.fuel, carried: d.carriedItems.length, label, toast: document.getElementById('toast').textContent };
});
check('Carried items near the fire can be thrown in with Interact', fire.fuel >= 55 && fire.carried === 0, JSON.stringify(fire));
check('Interact prompt changes to throwing nearby the fire', fire.label === 'THROW IN FIRE', fire.label);

// Axe attack and chopping.
const chop = await page.evaluate(async () => {
  const d = window.__nightsDebug;
  d.setInventoryOpen(false);
  d.equipTool('axe');
  d.state.attackCooldown = 0;
  const tree = d.treeData.find((t) => t.userData.choppable && !t.userData.falling && t.visible);
  d.player.position.set(tree.position.x + 1.55, d.getGroundHeight(tree.position.x + 1.55, tree.position.z), tree.position.z);
  d.player.rotation.y = Math.atan2(tree.position.x - d.player.position.x, tree.position.z - d.player.position.z);
  await new Promise((r) => setTimeout(r, 350));
  const target = d.state.targetTree === tree;
  const label = document.getElementById('attackLabel').textContent;
  const before = tree.userData.hits;
  d.attack();
  await new Promise((r) => setTimeout(r, 100));
  return {
    tool: d.state.equippedTool,
    target,
    label,
    before,
    after: tree.userData.hits,
    shake: tree.userData.shake,
    attackVisible: document.getElementById('attackBtn').classList.contains('visible')
  };
});
check('Attack/Chop button is visible and labeled for a tree', chop.tool === 'axe' && chop.attackVisible && chop.label === 'CHOP', JSON.stringify(chop));
check('Axe attack chops a nearby tree', chop.target && chop.after === chop.before - 1, JSON.stringify(chop));

// Felling drops logs and saplings to the ground without auto-pickup.
const fell = await page.evaluate(async () => {
  const d = window.__nightsDebug;
  const tree = d.state.targetTree;
  const woodBefore = d.groundItems.filter((i) => i.type === 'wood').length;
  const sapBefore = d.groundItems.filter((i) => i.type === 'sapling').length;
  d.fellTree(tree);
  await new Promise((r) => setTimeout(r, 2000));
  return {
    wood: d.groundItems.filter((i) => i.type === 'wood').length - woodBefore,
    sapling: d.groundItems.filter((i) => i.type === 'sapling').length - sapBefore,
    carried: d.carriedItems.length,
    backpack: d.state.backpack.wood
  };
});
check('Felling a tree drops logs and saplings on the ground', fell.wood >= 2 && fell.sapling >= 1, JSON.stringify(fell));
check('Dropped loot is not auto-collected', fell.carried === 0 && fell.backpack === 0, JSON.stringify(fell));

// Plant a carried sapling through Interact at a clean spot.
const planted = await page.evaluate(async () => {
  const d = window.__nightsDebug;
  d.unequipTool();
  d.player.position.set(70, d.getGroundHeight(70, 70), 70);
  d.player.rotation.y = 0;
  d.state.interactCooldown = 0;
  d.carriedItems.splice(0);
  const sap = d.spawnGroundItem('sapling', 70.2, 70.2, { velocityY: 0, pickupDelay: 0 });
  sap.landed = true;
  sap.mesh.position.y = sap.groundY + sap.restY;
  d.pickUpItem(sap);
  d.state.interactCooldown = 0;
  await new Promise((r) => setTimeout(r, 250));
  const label = document.getElementById('interactLabel').textContent;
  d.interact();
  await new Promise((r) => setTimeout(r, 300));
  return { carried: d.carriedItems.length, planted: d.plantedSaplings.length, label, toast: document.getElementById('toast').textContent };
});
check('Interact plants a carried sapling', planted.carried === 0 && planted.planted === 1, JSON.stringify(planted));

// Hunger drains over time.
const hunger = await page.evaluate(async () => {
  const d = window.__nightsDebug;
  d.state.hunger = 100;
  await new Promise((r) => setTimeout(r, 1500));
  return { hunger: d.state.hunger, text: document.getElementById('hungerText').textContent };
});
check('Hunger drains over time', hunger.hunger < 100, JSON.stringify(hunger));

// Layout: no overlaps at 740x360.
const layout = await page.evaluate(() => {
  const rects = {};
  for (const id of ['hotbar', 'actionCluster', 'joystickZone', 'hud']) {
    rects[id] = document.getElementById(id).getBoundingClientRect().toJSON();
  }
  const buttons = [...document.querySelectorAll('#actionCluster .action-btn')]
    .filter((b) => getComputedStyle(b).opacity !== '0')
    .map((b) => ({ id: b.id, r: b.getBoundingClientRect().toJSON() }));
  return { rects, buttons, viewport: { w: innerWidth, h: innerHeight } };
});
function intersects(a, b) {
  return !(a.right <= b.left || b.right <= a.left || a.bottom <= b.top || b.bottom <= a.top);
}
const rr = layout.rects;
const layoutPairs = [
  ['hotbar/action', rr.hotbar, rr.actionCluster],
  ['hotbar/joystick', rr.hotbar, rr.joystickZone],
  ['hud/hotbar', rr.hud, rr.hotbar],
  ['hud/action', rr.hud, rr.actionCluster]
];
for (const [name, a, b] of layoutPairs) {
  check(`No overlap: ${name}`, !intersects(a, b), JSON.stringify({ a, b }));
}
let buttonsOverlap = false;
for (let i = 0; i < layout.buttons.length; i += 1) {
  for (let j = i + 1; j < layout.buttons.length; j += 1) {
    if (intersects(layout.buttons[i].r, layout.buttons[j].r)) buttonsOverlap = true;
  }
}
check('Action arc buttons do not overlap', !buttonsOverlap, JSON.stringify(layout.buttons.map((b) => b.id)));
check('All visible action buttons are thumb-sized', layout.buttons.every((b) => b.r.width >= 48 && b.r.height >= 48), JSON.stringify(layout.buttons.map((b) => [b.id, b.r.width, b.r.height])));
check('Hotbar slots are thumb-sized', layout.rects.hotbar.height >= 44, JSON.stringify(layout.rects.hotbar));

// Combat regression: monsters can still be hit with the axe.
const combat = await page.evaluate(async () => {
  const d = window.__nightsDebug;
  d.spawnNightWave();
  d.equipTool('axe');
  d.state.attackCooldown = 0;
  const enemy = d.enemies.find((e) => e.visible && !e.userData.fading);
  const forward = { x: Math.sin(d.player.rotation.y), z: Math.cos(d.player.rotation.y) };
  enemy.position.set(d.player.position.x + forward.x * 1.8, d.player.position.y, d.player.position.z + forward.z * 1.8);
  const before = enemy.userData.health;
  d.attack();
  await new Promise((r) => setTimeout(r, 80));
  return { before, after: enemy.userData.health, visible: enemy.visible };
});
check('Monsters still take damage from axe attacks', combat.after === combat.before - 1, JSON.stringify(combat));

// Portrait: rotate overlay and pause.
await page.setViewport({ width: 360, height: 740, isMobile: true, hasTouch: true, deviceScaleFactor: 2 });
await wait(400);
const portrait = await page.evaluate(async () => {
  const d = window.__nightsDebug;
  const before = d.state.cycleTime;
  await new Promise((r) => setTimeout(r, 900));
  return {
    portrait: d.state.portrait,
    paused: d.state.paused,
    rotate: getComputedStyle(document.getElementById('rotateOverlay')).display,
    overlayTop: document.getElementById('rotateOverlay').getBoundingClientRect().toJSON(),
    before,
    after: d.state.cycleTime,
    text: document.querySelector('#rotateOverlay strong').textContent
  };
});
check('Portrait shows a full-screen rotate message', portrait.portrait && portrait.rotate === 'flex' && portrait.text === 'Rotate your phone', JSON.stringify(portrait));
check('Rotate overlay covers the whole viewport', portrait.overlayTop.width === 360 && portrait.overlayTop.height === 740, JSON.stringify(portrait.overlayTop));
check('Portrait pauses the game', portrait.paused && portrait.after === portrait.before, JSON.stringify(portrait));

// Back to landscape resumes.
await page.setViewport({ width: 740, height: 360, isMobile: true, hasTouch: true, deviceScaleFactor: 2 });
await wait(500);
const resumed = await page.evaluate(async () => {
  const d = window.__nightsDebug;
  const before = d.state.cycleTime;
  await new Promise((r) => setTimeout(r, 700));
  return {
    portrait: d.state.portrait,
    paused: d.state.paused,
    rotate: getComputedStyle(document.getElementById('rotateOverlay')).display,
    advanced: d.state.cycleTime !== before
  };
});
check('Landscape hides the rotate overlay and resumes the game', !resumed.portrait && !resumed.paused && resumed.rotate === 'none' && resumed.advanced, JSON.stringify(resumed));

check('No uncaught page errors', pageErrors.length === 0, pageErrors.join(' | '));
check('No console errors', consoleErrors.length === 0, consoleErrors.join(' | '));

await page.screenshot({ path: '/tmp/opencode/browser-test/new-final.png' });
await browser.close();

const failed = results.filter((r) => !r.pass);
console.log(`\n${results.length - failed.length}/${results.length} checks passed`);
if (failed.length > 0) {
  console.log('FAILED CHECKS:');
  for (const f of failed) console.log(` - ${f.name} :: ${f.detail}`);
  process.exit(1);
}

