import puppeteer from 'puppeteer-core';
const wait = (ms) => new Promise((r) => setTimeout(r, ms));
const browser = await puppeteer.launch({ executablePath: '/usr/bin/chromium', headless: 'new', args: ['--no-sandbox','--disable-dev-shm-usage','--enable-unsafe-swiftshader'] });
const page = await browser.newPage();
await page.setViewport({ width: 740, height: 360, isMobile: true, hasTouch: true, deviceScaleFactor: 2 });
page.on('pageerror', (e) => console.log('PAGEERR', String(e)));
await page.goto('http://localhost:3002/', { waitUntil: 'domcontentloaded' });
await page.waitForFunction(() => window.__nightsDebug, { timeout: 20000 });
await wait(400);
await page.tap('#startBtn');
await wait(500);
const probe = await page.evaluate(async () => {
  const d = window.__nightsDebug;
  const tree = d.treeData.find((t) => t.userData.choppable && !t.userData.falling && t.visible);
  d.player.position.set(tree.position.x + 1.55, d.getGroundHeight(tree.position.x + 1.55, tree.position.z), tree.position.z);
  await new Promise((r) => setTimeout(r, 200));
  const before = d.groundItems.length;
  d.fellTree(tree);
  const samples = [];
  for (let i = 0; i < 12; i += 1) {
    await new Promise((r) => setTimeout(r, 250));
    samples.push({
      t: (i + 1) * 250,
      falling: tree.userData.falling,
      progress: tree.userData.fallProgress,
      loot: tree.userData.lootDropped,
      visible: tree.visible,
      ground: d.groundItems.length,
      wood: d.groundItems.filter((x) => x.type === 'wood').length
    });
  }
  return { before, samples, err: null };
});
console.log(JSON.stringify(probe, null, 1));
await browser.close();

