import puppeteer from 'puppeteer-core';
const wait = (ms) => new Promise((r) => setTimeout(r, ms));
const browser = await puppeteer.launch({ executablePath: '/usr/bin/chromium', headless: 'new', args: ['--no-sandbox','--disable-dev-shm-usage','--enable-unsafe-swiftshader'] });
const page = await browser.newPage();
const errors = [];
page.on('console', (m) => { if (m.type() === 'error') errors.push(m.text()); });
page.on('pageerror', (e) => errors.push(String(e)));

async function load(w, h) {
  await page.setViewport({ width: w, height: h, isMobile: true, hasTouch: true, deviceScaleFactor: 2 });
  await page.goto('http://localhost:3002/', { waitUntil: 'domcontentloaded' });
  await page.waitForFunction(() => window.__nightsDebug, { timeout: 20000 });
  await wait(400);
  await page.tap('#startBtn');
  await wait(700);
}

function intersects(a, b) {
  return !(a.right <= b.left || b.right <= a.left || a.bottom <= b.top || b.bottom <= a.top);
}

for (const [w, h, tag] of [[844, 390, '844x390'], [640, 360, '640x360'], [568, 320, '568x320']]) {
  await load(w, h);
  const layout = await page.evaluate(() => {
    const ids = ['hud', 'hotbar', 'actionCluster', 'joystickZone'];
    const rects = {};
    for (const id of ids) rects[id] = document.getElementById(id).getBoundingClientRect().toJSON();
    const hidden = [];
    for (const id of ['attackBtn']) {
      const el = document.getElementById(id);
      if (getComputedStyle(el).opacity === '0') hidden.push(id);
    }
    const panelBottoms = [...document.querySelectorAll('#hud .panel')].map((p) => {
      const r = p.getBoundingClientRect();
      return { left: r.left, right: r.right, top: r.top, bottom: r.bottom };
    });
    return { rects, hidden, panelBottoms, vw: innerWidth, vh: innerHeight };
  });
  const pairs = [['hud/hotbar', layout.rects.hud, layout.rects.hotbar], ['hotbar/action', layout.rects.hotbar, layout.rects.actionCluster], ['hotbar/joy', layout.rects.hotbar, layout.rects.joystickZone], ['action/joy', layout.rects.actionCluster, layout.rects.joystickZone]];
  const overlaps = pairs.filter(([, a, b]) => intersects(a, b)).map(([n]) => n);
  const outOfBounds = Object.entries(layout.rects).filter(([, r]) => r.left < 0 || r.top < 0 || r.right > w + 0.5 || r.bottom > h + 0.5).map(([id]) => id);
  console.log(tag, JSON.stringify({ overlaps, outOfBounds, hidden: layout.hidden, rects: layout.rects, vw: layout.vw, vh: layout.vh }));
  await page.screenshot({ path: `/tmp/opencode/browser-test/shot-${tag}.png` });
}

// Axe equipped + backpack + inventory at 844x390.
await load(844, 390);
await page.tap('#axeSlot');
await wait(400);
await page.screenshot({ path: '/tmp/opencode/browser-test/shot-axe.png' });
await page.evaluate(() => {
  const d = window.__nightsDebug;
  d.state.backpack.wood = 4;
  d.state.backpack.sapling = 2;
  d.state.backpack.berry = 3;
  d.updateHud();
});
await page.tap('#backpackSlot');
await wait(400);
await page.screenshot({ path: '/tmp/opencode/browser-test/shot-backpack.png' });
await page.tap('#backpackSlot');
await wait(400);
await page.screenshot({ path: '/tmp/opencode/browser-test/shot-inventory.png' });

// Portrait.
await page.setViewport({ width: 390, height: 844, isMobile: true, hasTouch: true, deviceScaleFactor: 2 });
await wait(600);
await page.screenshot({ path: '/tmp/opencode/browser-test/shot-portrait.png' });
console.log('errors', errors);
