const browser = await puppeteer.launch({ executablePath: '/usr/bin/chromium', headless: 'new', args: ['--no-sandbox','--disable-dev-shm-usage','--enable-unsafe-swiftshader'] });
const page = await browser.newPage();
await page.setViewport({ width: 844, height: 390, isMobile: true, hasTouch: true, deviceScaleFactor: 2 });
const errors = [];
page.on('console', (m) => { if (m.type() === 'error') errors.push(m.text()); });
page.on('pageerror', (e) => errors.push(String(e)));
await page.goto('http://localhost:4012/', { waitUntil: 'networkidle0', timeout: 30000 });
await wait(600);
const before = await page.evaluate(() => ({
  canvas: !!document.getElementById('game'),
  hasDebug: !!window.__nightsDebug,
  rotate: getComputedStyle(document.getElementById('rotateOverlay')).display,
  hotbar: document.querySelectorAll('.hotbar-slot').length,
  startVisible: document.getElementById('startOverlay').classList.contains('visible')
}));
await page.tap('#startBtn');
await wait(1200);
const after = await page.evaluate(() => ({
  started: !document.getElementById('startOverlay').classList.contains('hidden'),
  overlayHidden: document.getElementById('startOverlay').classList.contains('hidden'),
  attackHidden: getComputedStyle(document.getElementById('attackBtn')).opacity,
  badge: document.getElementById('backpackBadge').textContent,
  fire: document.getElementById('fuelText').textContent,
  night: document.getElementById('nightText').textContent
}));
await page.tap('#axeSlot');
await wait(400);
const axe = await page.evaluate(() => ({
  equipped: document.getElementById('axeSlot').classList.contains('equipped'),
  attackVisible: document.getElementById('attackBtn').classList.contains('visible')
}));
console.log(JSON.stringify({ before, after, axe, errors }, null, 1));
await page.screenshot({ path: '/tmp/opencode/browser-test/prod.png' });
await browser.close();
if (errors.length || !after.overlayHidden || !axe.equipped || !axe.attackVisible) process.exit(1);

